// GENERATED by scripts/bundle-functions.mjs — do not edit by hand.
// Edit supabase/functions/_shared/* and <fn>/source.ts, then re-run the bundler.

// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into digital_twins.computed_fits[] and, for skill-match, the durable
// skill_fits table.
//
// Phase 8: every fit is versioned against the engine, the person's evidence
// and the requisition content; cached results are marked stale when any of
// them change. Adjacency and transferable support carry explicit limitations
// (never direct equivalence). The evidence section counts DISTINCT artifacts,
// not skill assertions.
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

/** Bump when the scoring semantics change — stale cached fits are recomputed. */
export const ENGINE_VERSION = "2";

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
}

export type Classification = "direct" | "adjacent" | "transferable" | "gap";

export interface FitItem {
  skill: string;
  classification: Classification;
  required_proficiency: number;
  candidate_proficiency: number | null;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  contribution: number | null;
  reason: string;
  /** Phase 8: honest limitation of this classification (never equivalence).
   *  Optional so legacy generated fits remain valid. */
  limitation?: string | null;
}

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  score: number;
  sections: {
    direct: { value: number; items: FitItem[] };
    adjacent: { value: number; items: FitItem[] };
    evidence: { value: number; artifact_count: number; threshold: number };
    seniority: { value: number; candidate_level: number; role_level: number };
  };
  classification: {
    direct: FitItem[];
    adjacent: FitItem[];
    transferable: FitItem[];
    gaps: FitItem[];
  };
  /** Phase 8: what the fit is versioned against (stale detection). Optional so
   *  legacy generated fits remain valid; missing versions are treated as stale. */
  versions?: {
    engine: string;
    evidence: string;
    requisition: string;
  };
  /** Phase 8: named horizon + assumption the fit was computed under. */
  assumptions?: {
    horizon: string;
    note: string;
  };
  computed_at: string;
}

// Validated weights — do not change.
export const MATCH_WEIGHTS = {
  direct: 0.5,
  adjacent: 0.25,
  evidence: 0.15,
  seniority: 0.1,
} as const;

export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;

/** Deterministic FNV-1a hex (uniquely named to avoid bundle collisions). */
export function graphFnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** Version hash over the requisition's skill content (phase 8 stale check). */
export function requisitionContentHash(
  requiredSkills: RequiredSkill[],
  futureSkills: RequiredSkill[],
  seniorityLevel: number
): string {
  const payload = [
    ...(requiredSkills ?? []).map((s) => `${s.skill}|${s.target_proficiency}`).sort(),
    ...(futureSkills ?? []).map((s) => `future:${s.skill}|${s.target_proficiency}`).sort(),
    `level:${seniorityLevel}`,
  ].join(";");
  return graphFnv1aHex(payload);
}

/** Version hash over the person's resolved skill claims (evidence version). */
export function claimHash(claims: SkillClaim[]): string {
  const payload = (claims ?? [])
    .map((c) => `${c.name}|${c.proficiency}|${c.evidence_source}|${c.verification_rigor}`)
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Phase 8: a cached fit is stale when the engine, the person's evidence or
 *  the requisition content changed since it was computed. */
export function fitIsStale(fit: FitRecord | null, current: { engine: string; evidence: string; requisition: string }): boolean {
  if (!fit) return true;
  const v = fit.versions;
  if (!v) return true; // pre-version fits are always stale
  return v.engine !== current.engine || v.evidence !== current.evidence || v.requisition !== current.requisition;
}

const HORIZON_LABEL: Record<string, string> = {
  current: "Current requirements — as recorded on the requisition today.",
  future: "12–24 month outlook — derived from the requisition's future_skills. Assumption: these skills are the expected demand; edit the requisition to change them.",
};

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
  /** Phase 8: distinct artifact count behind the claims (dedup, never
   *  one-per-assertion). Falls back to claim count when not supplied. */
  evidenceArtifactCount?: number;
  /** Phase 8: requisition content hash (stale detection). */
  requisitionVersion?: string;
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const graph = params.skillGraph;

  const directItems: FitItem[] = [];
  const adjacentItems: FitItem[] = [];
  const transferableItems: FitItem[] = [];
  const gapItems: FitItem[] = [];
  const directValues: number[] = [];
  const adjacentValues: number[] = [];

  let ownedCount = 0;
  for (const req of params.requiredSkills) {
    const own = params.candidateSkills.find((s) => norm(s.name) === norm(req.skill));
    const ownProficiency = own?.proficiency ?? 0;

    // S_direct: min(1, candidate/required) across ALL required skills — 0 for
    // skills not owned; partial proficiency still contributes its ratio.
    const ratio = own ? Math.min(1, ownProficiency / req.target_proficiency) : 0;
    directValues.push(ratio);

    if (own) {
      ownedCount++;
      if (ownProficiency >= req.target_proficiency) {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} required.`,
          limitation: null,
        });
      } else {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} — below the required bar.`,
          limitation: null,
        });
      }
      continue;
    }

    // Adjacent: no direct skill, but a real ADJACENT_TO edge exists (with the
    // candidate's proficiency weighting the edge). Never a direct equivalence.
    let bestAdj: { from: string; edge: GraphEdge; value: number } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
      if (edge) {
        const value = (claim.proficiency / 5) * edge.weight;
        if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value };
      }
    }
    if (bestAdj) {
      adjacentValues.push(bestAdj.value);
      adjacentItems.push({
        skill: req.skill,
        classification: "adjacent",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
        contribution: bestAdj.value,
        reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
        limitation: "Adjacent support is NOT direct equivalence: this person has no evidence for the required skill itself. Confirm real capability before relying on it.",
      });
      continue;
    }

    // Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or a
    // strong same-category relationship exists.
    let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
      if (edge) {
        transfer = { from: claim.name, edge, via: "edge" };
        break;
      }
      if (!transfer) {
        const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
        const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
        if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
          transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
        }
      }
    }
    if (transfer) {
      transferableItems.push({
        skill: req.skill,
        classification: "transferable",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: transfer.edge
          ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
          : null,
        contribution: null,
        reason: transfer.edge
          ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
          : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
        limitation: "Transferable support is the weakest signal: it does not establish any proficiency in the required skill and contributes no points to the score. Treat it as a development candidate, not capability.",
      });
      continue;
    }

    gapItems.push({
      skill: req.skill,
      classification: "gap",
      required_proficiency: req.target_proficiency,
      candidate_proficiency: ownProficiency || null,
      edge: null,
      contribution: null,
      reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
      limitation: null,
    });
  }

  const S_direct =
    directValues.length > 0
      ? directValues.reduce((a, b) => a + b, 0) / directValues.length
      : 0;

  const missing = params.requiredSkills.length - ownedCount; // skills not owned at all
  const S_adjacent =
    missing === 0
      ? 1 // nothing missing to be adjacent to
      : adjacentValues.length > 0
        ? adjacentValues.reduce((a, b) => a + b, 0) / missing
        : 0;

  // Phase 8: evidence counts DISTINCT artifacts (deduped by source), never one
  // point per skill assertion. Fallback to the claim count for legacy callers.
  const artifactCount =
    params.evidenceArtifactCount !== undefined
      ? params.evidenceArtifactCount
      : params.candidateSkills.filter((s) => s.verification_rigor === "high" || s.verification_rigor === "medium").length;
  const S_evidence = Math.min(1, artifactCount / threshold);

  const S_seniority = Math.max(0, 1 - 0.2 * Math.abs(params.candidateLevel - params.roleLevel));

  const score =
    MATCH_WEIGHTS.direct * S_direct +
    MATCH_WEIGHTS.adjacent * S_adjacent +
    MATCH_WEIGHTS.evidence * S_evidence +
    MATCH_WEIGHTS.seniority * S_seniority;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(score),
    sections: {
      direct: { value: round3(S_direct), items: directItems },
      adjacent: { value: round3(S_adjacent), items: adjacentItems },
      evidence: { value: round3(S_evidence), artifact_count: artifactCount, threshold },
      seniority: {
        value: round3(S_seniority),
        candidate_level: params.candidateLevel,
        role_level: params.roleLevel,
      },
    },
    classification: {
      direct: directItems,
      adjacent: adjacentItems,
      transferable: transferableItems,
      gaps: gapItems,
    },
    versions: {
      engine: ENGINE_VERSION,
      evidence: claimHash(params.candidateSkills),
      requisition: params.requisitionVersion ?? "unknown",
    },
    assumptions: {
      horizon: params.scenario === "future" ? "12–24 month outlook" : "Current",
      note: HORIZON_LABEL[params.scenario],
    },
    computed_at: params.computedAt ?? new Date().toISOString(),
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}


// ---------------------------------------------------------------------------
// WorkSense Qwen gateway client — server-managed config, strict output
// validation, one controlled repair attempt, sanitized telemetry.
// Called ONLY from backend functions. The tunnel URL / credentials never
// ship to the browser.
// ---------------------------------------------------------------------------

function getEnv(name: string, fallback: string): string {
  try {
    const deno = (globalThis as { Deno?: { env?: { get?: (n: string) => string | undefined } } }).Deno;
    const fromDeno = deno?.env?.get?.(name);
    if (fromDeno !== undefined) return fromDeno;
  } catch {
    /* node test env */
  }
  try {
    return (typeof process !== "undefined" ? process.env?.[name] : undefined) ?? fallback;
  } catch {
    return fallback;
  }
}

function getEnvInt(name: string, fallback: number): number {
  const v = Number(getEnv(name, String(fallback)));
  return Number.isFinite(v) && v > 0 ? Math.floor(v) : fallback;
}

// --- Server-managed settings (env with sane defaults) ----------------------
export const QWEN_BASE_URL = getEnv("QWEN_BASE_URL", "https://evolve-eternity-epidural.ngrok-free.dev/v1").replace(/\/+$/, "");
export const QWEN_MODEL = getEnv("QWEN_MODEL", "qwen3:4b-instruct-2507-q4_K_M");
export const QWEN_API_KEY = getEnv("QWEN_API_KEY", "local");
/** Optional real gateway auth (e.g. "Basic dXNlcjpwYXNz" or "Bearer x") for a protected tunnel. */
export const QWEN_GATEWAY_AUTH = getEnv("QWEN_GATEWAY_AUTH", "");
export const QWEN_TIMEOUT_MS = getEnvInt("QWEN_TIMEOUT_MS", 100000);
export const QWEN_MAX_INPUT_CHARS = getEnvInt("QWEN_MAX_INPUT_CHARS", 8000);
export const QWEN_MAX_TOKENS = getEnvInt("QWEN_MAX_TOKENS", 1600);

export type QwenErrorCode = "MODEL_UNAVAILABLE" | "MODEL_OUTPUT_INVALID" | "VALIDATION_ERROR" | "INPUT_TOO_LARGE";

export class QwenError extends Error {
  constructor(public code: QwenErrorCode, message: string) {
    super(message);
    this.name = "QwenError";
  }
}

// ---------------------------------------------------------------------------
// Untrusted-content handling (resume intake)
// ---------------------------------------------------------------------------

const INSTRUCTION_PATTERNS: RegExp[] = [
  /\bignore\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context|messages?|output)\b/gi,
  /\bdisregard\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context)\b/gi,
  /\bdo\s+not\s+(?:follow|obey|listen\s+to)\b/gi,
  /\byou\s+are\s+now\b/gi,
  /\bsystem\s+prompt\b/gi,
  /\bdeveloper\s+message\b/gi,
  /\bjailbreak\b/gi,
  /\boverride\s+(?:(?:your|the|system|developer)\s+)*(?:instructions?|rules?|prompt)\b/gi,
  /\bpretend\s+(?:to\s+|that\s+|you\s+)/gi,
  /\bsay\s+you\s+(?:are|have|would|can)\b/gi,
  /\bgive\s+(?:me\s+)?(?:a\s+)?100\s*%?\s*(?:match|fit|score)\b/gi,
  /\balways\s+(?:ignore|follow|obey)\b/gi,
  /\breveal\s+(?:your|the)\s+(?:system|instructions?|prompt)\b/gi,
];

/** Neutralize instruction-like phrases in untrusted resume text. */
export function sanitizeUntrusted(text: string): string {
  let out = String(text ?? "");
  for (const re of INSTRUCTION_PATTERNS) out = out.replace(re, "[redacted]");
  return out.trim();
}

/** Explicit delimiter marking untrusted content for the model. */
export function wrapUntrusted(text: string): string {
  return `<untrusted_input>\n${text}\n</untrusted_input>`;
}

// ---------------------------------------------------------------------------
// Strict JSON extraction — never salvage arbitrary brace substrings blindly.
// ---------------------------------------------------------------------------

export function isHtmlInterstitial(content: string): boolean {
  const head = String(content ?? "").slice(0, 400).trim().toLowerCase();
  return /^<!doctype|^<html|ngrok|502 bad gateway|504 gateway time-out|cloudflare/.test(head);
}

export function extractJsonStrict(content: string): unknown {
  const trimmed = String(content ?? "").trim();
  if (!trimmed) throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
  if (isHtmlInterstitial(trimmed)) {
    throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error, not model output).");
  }
  // 1) strict full parse
  try {
    return JSON.parse(trimmed);
  } catch {
    /* fall through */
  }
  // 2) strip markdown fences
  const fenced = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
  try {
    return JSON.parse(fenced);
  } catch {
    /* fall through */
  }
  // 3) balanced object extraction (only if the remainder is clearly a JSON object)
  const start = fenced.indexOf("{");
  const end = fenced.lastIndexOf("}");
  if (start !== -1 && end > start) {
    const candidate = fenced.slice(start, end + 1);
    // Reject if non-whitespace noise precedes the object or trails it.
    const prefixNoise = fenced.slice(0, start).trim();
    const suffixNoise = fenced.slice(end + 1).trim();
    if (prefixNoise.length <= 40 && suffixNoise.length <= 40) {
      try {
        return JSON.parse(candidate);
      } catch {
        throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: unbalanced JSON in response.");
      }
    }
  }
  throw new QwenError("MODEL_OUTPUT_INVALID", `qwen: no valid JSON object in response (${trimmed.slice(0, 160)}…)`);
}

// ---------------------------------------------------------------------------
// Sanitized telemetry — never log raw prompts.
// ---------------------------------------------------------------------------

function logMetric(entry: Record<string, string | number>) {
  console.log(`[qwen] ${Object.entries(entry).map(([k, v]) => `${k}=${v}`).join(" ")}`);
}

// ---------------------------------------------------------------------------
// OpenAI-compatible chat call
// ---------------------------------------------------------------------------

export async function callQwen(params: {
  system: string;
  user: string;
  json?: boolean;
  maxTokens?: number;
  temperature?: number;
  task?: string;
  timeoutMs?: number;
}): Promise<unknown> {
  const task = params.task ?? "generic";
  const started = Date.now();
  const inputChars = String(params.user ?? "").length;

  if (inputChars > QWEN_MAX_INPUT_CHARS) {
    logMetric({ task, status: "rejected", reason: "input_too_large", input_chars: inputChars });
    throw new QwenError("INPUT_TOO_LARGE", `Input exceeds the ${QWEN_MAX_INPUT_CHARS} character limit.`);
  }

  const messages: { role: string; content: string }[] = [
    { role: "system", content: params.system },
    { role: "user", content: params.user },
  ];
  const body: Record<string, unknown> = {
    model: QWEN_MODEL,
    messages,
    temperature: params.temperature ?? 0.2,
    max_tokens: params.maxTokens ?? QWEN_MAX_TOKENS,
    stream: false,
  };
  if (params.json) body.response_format = { type: "json_object" };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${QWEN_API_KEY}`,
  };
  if (QWEN_GATEWAY_AUTH) headers["Authorization"] = QWEN_GATEWAY_AUTH;

  const attempt = async (repairHint: boolean): Promise<unknown> => {
    const controller = new AbortController();
    const timeoutMs = params.timeoutMs ?? QWEN_TIMEOUT_MS;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let res: Response;
    try {
      res = await fetch(`${QWEN_BASE_URL}/chat/completions`, {
        method: "POST",
        headers,
        body: JSON.stringify(repairHint ? { ...body, messages: [...messages, { role: "user", content: "IMPORTANT: respond with ONLY valid JSON and nothing else. No markdown fences, no prose." }] } : body),
        signal: controller.signal,
      });
    } catch (err) {
      const timedOut = err instanceof Error && err.name === "AbortError";
      throw new QwenError("MODEL_UNAVAILABLE", timedOut ? `qwen: request timed out after ${timeoutMs}ms` : `qwen: network error (is the endpoint reachable?): ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      clearTimeout(timer);
    }

    if (!res.ok) {
      const text = await res.text();
      if (isHtmlInterstitial(text)) {
        throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error).");
      }
      throw new QwenError("MODEL_UNAVAILABLE", `qwen: HTTP ${res.status}: ${text.slice(0, 300)}`);
    }

    const data = await res.json();
    const content = data?.choices?.[0]?.message?.content;
    if (typeof content !== "string" || content.length === 0) {
      throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
    }
    if (!params.json) return content;

    const usage = data?.usage;
    const latency = Date.now() - started;
    try {
      const parsed = extractJsonStrict(content);
      logMetric({
        task, status: "ok", latency_ms: latency,
        model: QWEN_MODEL, out_chars: content.length,
        tokens_in: usage?.prompt_tokens ?? 0, tokens_out: usage?.completion_tokens ?? 0,
        input_chars: inputChars,
      });
      return parsed;
    } catch (err) {
      if (err instanceof QwenError) {
        if (err.code === "MODEL_OUTPUT_INVALID" && !repairHint) {
          // Exactly one controlled repair attempt.
          logMetric({ task, status: "repair", latency_ms: latency, reason: err.message.slice(0, 80) });
          return attempt(true);
        }
        logMetric({ task, status: "failed", latency_ms: latency, code: err.code });
        throw err;
      }
      throw err;
    }
  };

  return attempt(false);
}


// ---------------------------------------------------------------------------
// Durable model-job records — honest constrained alternative to a background
// worker: the serverless runtime has no worker/queue, so jobs execute inline
// but persist their full lifecycle. Refresh recovers status; a job stuck in
// 'running' indicates an interrupted invocation and is re-runnable. Input
// content is never stored — only a hash.
// ---------------------------------------------------------------------------

export const JOB_SCHEMA_VERSION = "v1";

export interface JobRow {
  id: string;
  org_id: string;
  actor_id: string;
  task: string;
  input_hash: string;
  schema_version: string;
  prompt_version: string;
  model: string;
  status: "queued" | "running" | "succeeded" | "failed";
  retry_count: number;
  latency_ms: number | null;
  tokens_in: number | null;
  tokens_out: number | null;
  error_code: string | null;
  error_message: string | null;
  output: unknown;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
}

/** Open duplicate for the same actor+task+input while still queued/running.
 *  A queued/running job older than 5 minutes is treated as stale (an
 *  interrupted serverless invocation) so a retry can proceed. */
export async function findOpenJob(supabase, orgId: string, actorId: string, task: string, inputHash: string) {
  const { data, error } = await supabase
    .from("model_jobs")
    .select("id, status, created_at, started_at")
    .eq("org_id", orgId)
    .eq("actor_id", actorId)
    .eq("task", task)
    .eq("input_hash", inputHash)
    .in("status", ["queued", "running"])
    .maybeSingle();
  if (error) throw error;
  if (!data) return null;
  const ageMs = Date.now() - new Date(data.created_at).getTime();
  if (ageMs >= 5 * 60 * 1000) return null; // stale -> allow a fresh attempt
  return { id: data.id };
}

export async function createJob(supabase, params: {
  orgId: string;
  actorId: string;
  task: string;
  inputHash: string;
  promptVersion: string;
  model: string;
}) {
  const { data, error } = await supabase
    .from("model_jobs")
    .insert({
      org_id: params.orgId,
      actor_id: params.actorId,
      task: params.task,
      input_hash: params.inputHash,
      schema_version: JOB_SCHEMA_VERSION,
      prompt_version: params.promptVersion,
      model: params.model,
      status: "queued",
      retry_count: 0,
    })
    .select("id, created_at")
    .single();
  if (error) throw error;
  return data as { id: string; created_at: string };
}

export async function markJobRunning(supabase, id: string) {
  await supabase.from("model_jobs").update({ status: "running", started_at: new Date().toISOString() }).eq("id", id);
}

export async function finishJob(supabase, id: string, params: {
  status: "succeeded" | "failed";
  output?: unknown;
  latencyMs?: number;
  tokensIn?: number;
  tokensOut?: number;
  errorCode?: string;
  errorMessage?: string;
}) {
  await supabase
    .from("model_jobs")
    .update({
      status: params.status,
      output: params.output ?? null,
      latency_ms: params.latencyMs ?? null,
      tokens_in: params.tokensIn ?? null,
      tokens_out: params.tokensOut ?? null,
      error_code: params.errorCode ?? null,
      error_message: params.errorMessage ?? null,
      finished_at: new Date().toISOString(),
    })
    .eq("id", id);
}

export async function getJob(supabase, id: string): Promise<JobRow | null> {
  const { data, error } = await supabase.from("model_jobs").select("*").eq("id", id).maybeSingle();
  if (error) throw error;
  return (data as JobRow | null) ?? null;
}

/** Non-cryptographic input hash (deterministic, used only for dedup). */
export function hashInput(text: string): string {
  let h = 0;
  const s = String(text ?? "");
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(16);
}


// ---------------------------------------------------------------------------
// Per-task runtime schema + semantic validation for Qwen outputs.
// Runs AFTER generation regardless of provider structured-output support.
// No invalid/partial model output becomes trusted domain data.
// ---------------------------------------------------------------------------

export type ValidationResult = { ok: true } | { ok: false; errors: string[] };

const isStr = (v: unknown): v is string => typeof v === "string";
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isArr = (v: unknown): v is unknown[] => Array.isArray(v);
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

const TIERS = ["FOUNDATIONAL", "INTERMEDIATE", "ADVANCED", "EXPERT"];
const EVAL_TIERS = ["Red Flag", "Developing", "Competent-Baseline", "Advanced", "Master-Architectural"];
const EVAL_RECS = ["Select", "Move Forward", "Reject"];
const POLICY_STATUS = ["grounded_response", "insufficient_evidence"];
const TREND = ["up", "flat", "down"];
const SIGNOFF = ["HR_EXECUTIVE", "MANAGER"];

function fail(errors: string[]): ValidationResult {
  return errors.length === 0 ? { ok: true } : { ok: false, errors };
}

// 1) Resume Evidence Extraction (6.1)
export function validateResumeExtraction(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.full_name) || d.full_name.trim().length === 0) errors.push("full_name must be a non-empty string");
  if (!isNum(d.years_experience) || d.years_experience < 0 || d.years_experience > 60) errors.push("years_experience must be 0..60");
  const skills = d.extracted_skills;
  if (!isArr(skills)) errors.push("extracted_skills must be an array");
  else {
    for (const raw of skills) {
      const s = isObj(raw) ? raw : null;
      if (!s || !isStr(s.skill_name) || s.skill_name.trim().length === 0 || s.skill_name.length > 80) errors.push("skill_name missing/too long");
      if (!s || !isNum(s.years) || s.years < 0 || s.years > 50) errors.push("skill years out of bounds");
      if (!s || !isStr(s.proficiency_tier) || !TIERS.includes(s.proficiency_tier)) errors.push(`proficiency_tier must be one of ${TIERS.join(",")}`);
      if (!s || !isStr(s.evidence_quote) || s.evidence_quote.length > 200) errors.push("evidence_quote must be a short string");
    }
  }
  if (!isArr(d.verified_projects)) errors.push("verified_projects must be an array");
  return fail(errors);
}

// 2) 5-Tier Interview Rubric (6.2)
export function validateRubric(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.competency) || d.competency.trim().length === 0) errors.push("competency missing");
  if (!isStr(d.question) || d.question.trim().length === 0) errors.push("question missing");
  if (!isArr(d.follow_up_probes) || d.follow_up_probes.length !== 2 || d.follow_up_probes.some((p) => !isStr(p) || p.length === 0)) {
    errors.push("follow_up_probes must contain exactly 2 non-empty strings");
  }
  if (!isObj(d.rubric)) errors.push("rubric must be an object");
  else {
    for (let i = 1; i <= 5; i++) {
      const k = `tier_${i}` as const;
      if (!isStr(d.rubric[k]) || (d.rubric[k] as string).trim().length === 0) errors.push(`rubric.${k} must be a non-empty string`);
    }
  }
  return fail(errors);
}

// 3) Assessment Evaluation
export function validateEvaluation(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isArr(d.evaluations)) errors.push("evaluations must be an array");
  else {
    for (const raw of d.evaluations) {
      const e = isObj(raw) ? raw : null;
      if (!e) { errors.push("evaluation item not an object"); continue; }
      if (!isStr(e.competency) || e.competency.trim().length === 0) errors.push("evaluation competency missing");
      if (!isStr(e.tier) || !EVAL_TIERS.includes(e.tier)) errors.push(`tier must be one of ${EVAL_TIERS.join("|")}`);
      if (!isNum(e.score) || e.score < 1 || e.score > 5 || !Number.isInteger(e.score)) errors.push("score must be an integer 1..5");
      if (!isStr(e.evidence) || e.evidence.trim().length === 0) errors.push("evidence missing (assessment must be evidence-linked)");
    }
  }
  if (!isStr(d.overall_recommendation) || !EVAL_RECS.includes(d.overall_recommendation)) errors.push(`overall_recommendation must be one of ${EVAL_RECS.join("|")}`);
  return fail(errors);
}

// 4) Grounded Policy Answer (6.3)
export function validatePolicyAnswer(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.status) || !POLICY_STATUS.includes(d.status)) errors.push(`status must be one of ${POLICY_STATUS.join("|")}`);
  if (!isStr(d.answer)) errors.push("answer must be a string");
  if (!isArr(d.citations)) errors.push("citations must be an array");
  else {
    for (const raw of d.citations) {
      const c = isObj(raw) ? raw : null;
      if (!c) { errors.push("citation not an object"); continue; }
      if (!isStr(c.doc_code) || !/^POL-/.test(c.doc_code)) errors.push("citation doc_code must start with POL-");
      if (c.version !== undefined && c.version !== null && !isStr(c.version) && !isNum(c.version)) errors.push("citation version must be a string or number");
      if (!isStr(c.section) || c.section.trim().length === 0) errors.push("citation section missing");
      if (!isStr(c.exact_quote) || c.exact_quote.trim().length === 0) errors.push("citation exact_quote must be non-empty");
    }
  }
  return fail(errors);
}

// 5) Performance Narrative
export function validatePerformanceNarrative(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.strengths) || d.strengths.trim().length === 0) errors.push("strengths missing");
  if (!isStr(d.growth_areas) || d.growth_areas.trim().length === 0) errors.push("growth_areas missing");
  if (!isStr(d.trend_direction) || !TREND.includes(d.trend_direction)) errors.push(`trend_direction must be one of ${TREND.join("|")}`);
  if (!isNum(d.confidence) || d.confidence < 0 || d.confidence > 1) errors.push("confidence must be 0..1");
  return fail(errors);
}

// 6) Recommendation Explanation (6.4)
export function validateRecommendationExplanation(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.title) || d.title.trim().length === 0) errors.push("title missing");
  if (!isStr(d.executive_summary) || d.executive_summary.trim().length < 20) errors.push("executive_summary too short");
  if (!isObj(d.proposed_action) || !isStr(d.proposed_action.action_type) || !isStr(d.proposed_action.target_entity_id)) {
    errors.push("proposed_action.action_type/target_entity_id required");
  }
  if (!isStr(d.required_human_signoff_role) || !SIGNOFF.includes(d.required_human_signoff_role)) {
    errors.push(`required_human_signoff_role must be one of ${SIGNOFF.join("|")}`);
  }
  return fail(errors);
}

// 8) Assessment Evaluation (Phase 6) — per-competency judgment block emitted by
// the model. Semantic checks (quotes exist, score bounds vs rubric anchors) run
// in assessment.ts validateJudgmentItem, which has the rubric + answers context.
const ASSESSMENT_JUDGMENTS = ["1", "2", "3", "4", "5", "NOT_ASSESSED", "INSUFFICIENT_EVIDENCE"];

export function validateAssessmentJudgment(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isArr(d.judgments)) errors.push("judgments must be an array");
  else {
    for (const raw of d.judgments) {
      const j = isObj(raw) ? raw : null;
      if (!j) { errors.push("judgment item not an object"); continue; }
      if (!isStr(j.competency) || j.competency.trim().length === 0) errors.push("judgment competency missing");
      if (!isStr(j.judgment) || !ASSESSMENT_JUDGMENTS.includes(j.judgment)) {
        errors.push(`judgment must be one of ${ASSESSMENT_JUDGMENTS.join("|")}`);
      }
      if (!isArr(j.evidence_quotes)) errors.push("judgment evidence_quotes must be an array");
      else if (j.evidence_quotes.some((q) => !isStr(q))) errors.push("evidence_quotes entries must be strings");
      if (j.anchor_ref !== undefined && j.anchor_ref !== null && !isStr(j.anchor_ref)) errors.push("anchor_ref must be a string");
      if (j.uncertainty !== undefined && (!isNum(j.uncertainty) || j.uncertainty < 0 || j.uncertainty > 1)) {
        errors.push("uncertainty must be a number 0..1");
      }
      if (j.suggested_follow_up !== undefined && j.suggested_follow_up !== null && !isStr(j.suggested_follow_up)) {
        errors.push("suggested_follow_up must be a string");
      }
      // Phase 5: dimension scores (correctness/reasoning/trade_offs/communication).
      const dimScores = ["1", "2", "3", "4", "5", "NA"];
      if (j.dimensions !== undefined && j.dimensions !== null) {
        if (!isObj(j.dimensions)) errors.push("dimensions must be an object");
        else {
          for (const [name, v] of Object.entries(j.dimensions as Record<string, unknown>)) {
            if (!["correctness", "reasoning", "trade_offs", "communication"].includes(name)) {
              errors.push(`dimensions.${name} is not a supported dimension`);
            } else if (typeof v !== "string" || !dimScores.includes(v)) {
              errors.push(`dimensions.${name} must be one of ${dimScores.join("|")}`);
            }
          }
        }
      }
    }
  }
  if (!isStr(d.summary) || d.summary.trim().length === 0) errors.push("summary missing");
  return fail(errors);
}

// 7) Rich Resume Review (Phase 4) — the full traceable extraction schema.
export function validateResumeReview(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.full_name) || d.full_name.trim().length === 0) errors.push("full_name must be a non-empty string");

  const contact = d.contact;
  if (contact !== undefined && contact !== null && !isObj(contact)) errors.push("contact must be an object");
  else if (isObj(contact)) {
    for (const k of ["email", "phone", "location", "linkedin"]) {
      if (contact[k] !== undefined && contact[k] !== null && !isStr(contact[k])) errors.push(`contact.${k} must be a string`);
      if (isStr(contact[k]) && (contact[k] as string).length > 200) errors.push(`contact.${k} too long`);
    }
  }

  const checkRoles = (arr: unknown, label: string) => {
    if (!isArr(arr)) {
      errors.push(`${label} must be an array`);
      return;
    }
    for (const raw of arr) {
      const r = isObj(raw) ? raw : null;
      if (!r) {
        errors.push(`${label}: entry must be an object`);
        return;
      }
      if (!isStr(r.title) || r.title.trim().length === 0) errors.push(`${label}: title missing`);
      if (!isStr(r.company)) errors.push(`${label}: company must be a string`);
      if (r.start !== undefined && !isStr(r.start)) errors.push(`${label}: start must be a string`);
      if (r.end !== undefined && !isStr(r.end)) errors.push(`${label}: end must be a string`);
      if (r.years_claimed !== undefined && (!isNum(r.years_claimed) || r.years_claimed < 0 || r.years_claimed > 60)) errors.push(`${label}: years_claimed must be 0..60`);
      if (!isStr(r.quote) || r.quote.trim().length === 0 || r.quote.length > 300) errors.push(`${label}: quote must be a short string`);
    }
  };
  checkRoles(d.roles, "roles");

  const checkSimple = (arr: unknown, label: string, quoteRequired: boolean) => {
    if (!isArr(arr)) {
      errors.push(`${label} must be an array`);
      return;
    }
    for (const raw of arr) {
      const r = isObj(raw) ? raw : null;
      if (!r) {
        errors.push(`${label}: entry must be an object`);
        return;
      }
      const names = label === "education" ? ["institution", "degree", "year"] : label === "certifications" ? ["name", "issuer", "year"] : ["name", "role"];
      for (const k of names) if (!isStr(r[k])) errors.push(`${label}: ${k} must be a string`);
      if (label === "projects") {
        if (!isArr(r.tech_stack)) errors.push(`${label}: tech_stack must be an array`);
        if (r.impact_metric !== undefined && !isStr(r.impact_metric)) errors.push(`${label}: impact_metric must be a string`);
      }
      if (quoteRequired && (!isStr(r.quote) || r.quote.trim().length === 0 || r.quote.length > 300)) errors.push(`${label}: quote must be a short string`);
    }
  };
  checkSimple(d.education, "education", true);
  checkSimple(d.certifications, "certifications", true);
  checkSimple(d.projects, "projects", true);

  const claims = d.skill_claims;
  if (!isArr(claims)) errors.push("skill_claims must be an array");
  else {
    for (const raw of claims) {
      const c = isObj(raw) ? raw : null;
      if (!c) {
        errors.push("skill_claims: entry must be an object");
        return;
      }
      if (!isStr(c.skill) || c.skill.trim().length === 0 || c.skill.length > 80) errors.push("skill_claims: skill missing/too long");
      if (c.years !== undefined && (!isNum(c.years) || c.years < 0 || c.years > 50)) errors.push("skill_claims: years out of bounds");
      if (!isStr(c.proficiency_tier) || !TIERS.includes(c.proficiency_tier)) errors.push(`skill_claims: proficiency_tier must be one of ${TIERS.join(",")}`);
      if (!isStr(c.quote) || c.quote.trim().length === 0 || c.quote.length > 300) errors.push("skill_claims: quote must be a short string");
      if (!isStr(c.association) || !["explicit", "inferred", "unsupported"].includes(c.association)) {
        errors.push("skill_claims: association must be explicit|inferred|unsupported");
      }
    }
  }
  if (!isArr(d.ambiguities)) errors.push("ambiguities must be an array");
  if (!isArr(d.conflicts)) errors.push("conflicts must be an array");
  return fail(errors);
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";




const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const BIAS_SYSTEM = `You are the WorkSense Interview Architect. For the given role, competency, and the candidate's specific Adjacent/Transferable/Gap items, generate one question, two follow-up probes, and a strict 5-tier OBSERVABLE behavioral rubric (concrete behaviors, not adjectives). Tier 1 = concrete red-flag behavior. Tier 3 = solid role-baseline behavior. Tier 5 = master/architectural-level behavior. Bias the question toward probing the candidate's specific adjacent/transferable claim, not a generic question.
Respond with JSON only:
{"competency":"string","question":"string","follow_up_probes":["string","string"],
"rubric":{"tier_1":"string","tier_2":"string","tier_3":"string","tier_4":"string","tier_5":"string"}}`;

const TIER_KEYS = ["tier_1", "tier_2", "tier_3", "tier_4", "tier_5"] as const;

function shapeRubric(parsed: { competency?: string; question?: string; follow_up_probes?: string[]; rubric?: Partial<Record<(typeof TIER_KEYS)[number], string>> }, fallbackComp: string) {
  return {
    competency: (parsed.competency ?? fallbackComp).replace(/\s*\(.*\)\s*$/, "").trim() || fallbackComp,
    question: parsed.question ?? `Tell me about your experience with ${fallbackComp}.`,
    follow_up_probes: (parsed.follow_up_probes ?? []).slice(0, 2),
    rubric: {
      tier_1: parsed.rubric?.tier_1 ?? "",
      tier_2: parsed.rubric?.tier_2 ?? "",
      tier_3: parsed.rubric?.tier_3 ?? "",
      tier_4: parsed.rubric?.tier_4 ?? "",
      tier_5: parsed.rubric?.tier_5 ?? "",
    },
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  let jobId: string | null = null;
  try {

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller || !["hr_executive", "recruiter"].includes(caller.role)) {
    return json({ error: "FORBIDDEN", message: "Recruitment access required." }, 403);
  }

  let body: { twin_id?: string; req_id?: string } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const twinId = (body.twin_id ?? "").trim();
  const reqId = (body.req_id ?? "").trim();
  if (!twinId || !reqId) return json({ error: "VALIDATION_ERROR", message: "twin_id and req_id are required." }, 400);

  const { data: twin, error: twinErr } = await supabase
    .from("digital_twins")
    .select("id, role, org_id, name, verified_skills, seniority_level, computed_fits, audit_events, interview_rubrics")
    .eq("id", twinId)
    .maybeSingle();
  if (twinErr || !twin || twin.role !== "candidate") return json({ error: "NOT_FOUND" }, 404);

  const { data: reqRow, error: reqErr } = await supabase
    .from("job_requisitions")
    .select("id, org_id, title, required_skills, future_skills, seniority_level, rubrics, audit_events")
    .eq("id", reqId)
    .maybeSingle();
  if (reqErr || !reqRow) return json({ error: "NOT_FOUND" }, 404);
  if (reqRow.org_id !== caller.org_id || reqRow.org_id !== twin.org_id) return json({ error: "FORBIDDEN" }, 403);

  // Durable job lifecycle for the (expensive) kit generation.
  const jobStartedAt = Date.now();
  const inputHash = hashInput(`${twinId}|${reqId}`);
  const open = await findOpenJob(supabase, caller.org_id, caller.id, "interview_kit", inputHash);
  if (open) {
    return json({ error: "CONFLICT", message: "An interview kit for this candidate and role is already being generated.", job_id: open.id }, 409);
  }
  const job = await createJob(supabase, {
    orgId: caller.org_id, actorId: uid, task: "interview_kit", inputHash,
    promptVersion: "interview-kit-v1", model: QWEN_MODEL,
  });
  jobId = job.id;
  await markJobRunning(supabase, job.id);

  // 1) Reuse cached rubrics; generate any missing competencies (cached per role).
  const required = (reqRow.required_skills ?? []) as { skill: string; target_proficiency: number }[];
  let rubrics = (reqRow.rubrics ?? []) as { competency: string; question: string; follow_up_probes: string[]; rubric: Record<string, string> }[];
  const have = new Set(rubrics.map((r) => r.competency.toLowerCase()));
  const missing = [...required.map((r) => r.skill), "Collaboration"].filter((c) => !have.has(c.toLowerCase()));

  // Batch missing competencies in bounded chunks (local 4B model: keep each
  // generation call small enough to stay under the runtime execution cap
  // while avoiding numerous tiny sequential calls).
  if (missing.length > 0) {
    for (let i = 0; i < missing.length; i += 2) {
      const chunk = missing.slice(i, i + 2);
      const parsed = (await callQwen({
        json: true,
        temperature: 0.3,
        maxTokens: 1200,
        task: "interview_kit_rubrics",
        system:
          'You are the WorkSense Interview Architect. For each given competency, generate one question, two follow-up probes, and a strict 5-tier OBSERVABLE behavioral rubric (concrete behaviors, not adjectives). Tier 1 = concrete red-flag behavior. Tier 3 = solid role-baseline behavior. Tier 5 = master/architectural-level behavior.\nRespond with JSON only:\n{"rubrics":[{"competency":"string","question":"string","follow_up_probes":["string","string"],"rubric":{"tier_1":"string","tier_2":"string","tier_3":"string","tier_4":"string","tier_5":"string"}}]}',
        user: `Role: ${reqRow.title}. Competencies: ${chunk.join(", ")}. Produce the rubrics array as JSON.`,
      })) as { rubrics?: unknown[] };

      for (const item of parsed.rubrics ?? []) {
        const valid = validateRubric(item);
        if (valid.ok === false) throw new QwenError("MODEL_OUTPUT_INVALID", `Rubric failed validation: ${valid.errors.join("; ")}`);
        const r = item as { competency?: string; question?: string; follow_up_probes?: string[]; rubric: Record<string, string> };
        const name = (r.competency ?? "").replace(/\s*\(.*\)\s*$/, "").trim();
        if (!name) continue;
        rubrics = rubrics.filter((x) => x.competency.toLowerCase() !== name.toLowerCase());
        rubrics.push({ competency: name, question: r.question ?? "", follow_up_probes: (r.follow_up_probes ?? []).slice(0, 2), rubric: r.rubric });
      }
    }
    await supabase.from("job_requisitions").update({ rubrics }).eq("id", reqId);
  }

  // 2) Fit card (persisted) — reuse the Skill Graph output to bias the probes.
  const fits = (twin.computed_fits ?? []) as { target_id: string; scenario: string; score: number; classification: { adjacent: { skill: string }[]; transferable: { skill: string }[]; gaps: { skill: string }[] } }[];
  let fit = fits.find((f) => f.target_id === reqId && f.scenario === "current");
  if (!fit) {
    const { data: graphRows } = await supabase
      .from("skill_graph")
      .select("skill, category, outgoing_edges")
      .eq("org_id", twin.org_id);
    const now = new Date().toISOString();
    fit = computeFit({
      candidateSkills: twin.verified_skills ?? [],
      candidateLevel: twin.seniority_level ?? 3,
      requiredSkills: reqRow.required_skills ?? [],
      roleLevel: reqRow.seniority_level ?? 3,
      skillGraph: graphRows ?? [],
      target: { type: "requisition", id: reqRow.id, title: reqRow.title },
      scenario: "current",
      computedAt: now,
    }) as unknown as typeof fit;
    await supabase
      .from("digital_twins")
      .update({
        computed_fits: [...fits.filter((f) => !(f.target_id === reqId && f.scenario === "current")), fit],
        audit_events: [
          ...(twin.audit_events ?? []),
          { actor: caller.email ?? uid, action: "match_computed", note: `Match vs ${reqRow.title}: ${fit.score.toFixed(3)}`, timestamp: now },
        ],
      })
      .eq("id", twinId);
  }

  const focusItems = [...(fit.classification.gaps ?? []), ...(fit.classification.adjacent ?? []), ...(fit.classification.transferable ?? [])].slice(0, 3);

  // One 6.2 call, biased toward the candidate's top focus item from their Fit card.
  let biasedProbe: { competency: string; question: string; follow_up_probes: string[]; rubric: Record<string, string> } | null = null;
  if (focusItems.length > 0) {
    const parsed = (await callQwen({
      json: true,
      temperature: 0.3,
      maxTokens: 900,
      task: "interview_kit_probe",
      system: BIAS_SYSTEM,
      user: `Role: ${reqRow.title}. Candidate's Adjacent/Transferable/Gap items: ${focusItems.map((i) => i.skill).join(", ")}. Bias the question toward the top item and produce the rubric JSON.`,
    })) as unknown;
    const valid = validateRubric(parsed);
    if (valid.ok === false) throw new QwenError("MODEL_OUTPUT_INVALID", `Biased probe failed validation: ${valid.errors.join("; ")}`);
    biasedProbe = shapeRubric(parsed as { competency?: string; question?: string; follow_up_probes?: string[]; rubric?: Partial<Record<(typeof TIER_KEYS)[number], string>> }, focusItems[0].skill);
    biasedProbe.competency = focusItems[0].skill; // pin to the actual focus skill
  }

  const kit = {
    type: "interview_kit",
    req_id: reqRow.id,
    req_title: reqRow.title,
    candidate_name: twin.name,
    score: fit.score,
    focus_items: focusItems.map((i) => i.skill),
    biased_probe: biasedProbe,
    competencies: rubrics,
    created_at: new Date().toISOString(),
  };

  const now = new Date().toISOString();
  await supabase
    .from("digital_twins")
    .update({
      interview_rubrics: [...(twin.interview_rubrics ?? []), kit],
      audit_events: [
        ...(twin.audit_events ?? []),
        { actor: caller.email ?? uid, action: "interview_kit_generated", note: `Interview kit for ${reqRow.title} (score ${fit.score.toFixed(2)}).`, timestamp: now },
      ],
    })
    .eq("id", twinId);

  await finishJob(supabase, job.id, { status: "succeeded", output: { score: fit.score, focus_items: kit.focus_items }, latencyMs: Date.now() - jobStartedAt });

  return json({ ok: true, job_id: job.id, status: "succeeded", kit });
  } catch (err) {
    if (jobId) {
      await finishJob(supabase, jobId, { status: "failed", errorCode: err instanceof QwenError ? err.code : "INTERNAL", errorMessage: err instanceof Error ? err.message : "unknown" }).catch(() => undefined);
    }
    return json({ error: err instanceof QwenError ? err.code : "INTERNAL", message: err instanceof Error ? err.message : "unknown" });
  }
});